# Generated by tools/render_controls.py — edit the data files, not this file.
#
# Rule:        CKV_AWS_274 (checkov 3.3.16)
# Applies to:  aws_iam_policy_attachment
# Read with:   aws_iam_policy(policy_arn: "arn:#{input('aws_partition')}:iam::aws:policy/AdministratorAccess") — an account-level singleton, so there is nothing to enumerate
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

control 'CKV_AWS_274' do
  title 'Disallow IAM roles, users, and groups from using the AWS AdministratorAccess policy'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the account's own aws_iam_policy_attachment, which is a single object
    rather than a collection.
  DESC

  desc 'rationale', <<~RATIONALE
    AdministratorAccess grants every action on every resource. A principal
    holding it is bounded by nothing the account can express — no resource
    policy, no tag condition, no service scope — so least privilege is not
    partially satisfied for it, it is absent. Asserting that nothing is
    attached to the policy is the only test that can be made without
    evaluating what every attached principal is actually for, and it is the
    same assertion Checkov makes, taken against attachments that exist
    rather than attachments that were written down.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: Disallow IAM roles, users, and groups from using the
    AWS AdministratorAccess policy
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_iam_policy_attachment:

      # Replace the AWS-managed AdministratorAccess attachment with a
      # customer-managed policy scoped to what the principal actually does.
      # There is no in-place "narrow AdministratorAccess" — the managed policy
      # is owned by AWS and cannot be edited — so the fix is always a swap.
      resource "aws_iam_policy" "platform_operate" {
        name        = "platform-operate"
        description = "Day-two operations for the platform team"

        policy = jsonencode({
          Version = "2012-10-17"
          Statement = [{
            Effect   = "Allow"
            Action   = ["ecs:*", "logs:*", "cloudwatch:*", "ssm:GetParameter*"]
            Resource = "*"
            Condition = {
              StringEquals = {
                "aws:RequestedRegion" = ["us-east-1"]
              }
            }
          }]
        })
      }

      resource "aws_iam_role_policy_attachment" "platform_operate" {
        role       = aws_iam_role.platform.name
        policy_arn = aws_iam_policy.platform_operate.arn
      }

      # If a break-glass administrator is genuinely required, give it its own
      # role with a hard condition rather than leaving the managed policy on a
      # day-to-day principal.
      resource "aws_iam_role" "break_glass" {
        name = "break-glass-admin"

        assume_role_policy = jsonencode({
          Version = "2012-10-17"
          Statement = [{
            Effect    = "Allow"
            Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
            Action    = "sts:AssumeRole"
            Condition = {
              Bool           = { "aws:MultiFactorAuthPresent" = "true" }
              NumericLessThan = { "aws:MultiFactorAuthAge" = "900" }
            }
          }]
        })
      }

    Out of band — aws_iam_policy_attachment:

      # Who holds it right now — roles, users and groups, in one call.
      aws iam list-entities-for-policy --policy-arn arn:aws:iam::aws:policy/AdministratorAccess
      aws iam detach-role-policy --role-name <role> --policy-arn arn:aws:iam::aws:policy/AdministratorAccess
      aws iam detach-user-policy --user-name <user> --policy-arn arn:aws:iam::aws:policy/AdministratorAccess
      aws iam detach-group-policy --group-name <group> --policy-arn arn:aws:iam::aws:policy/AdministratorAccess

    Note (aws_iam_policy_attachment): Create and attach the replacement BEFORE
    detaching, and verify the principal can still do its job — a detach here can
    lock out the only identity able to repair the account. Check IAM Identity
    Center too: an attachment made through a permission set is re-provisioned
    onto the AWSReservedSSO_* role after any manual detach, so it must be
    removed at the permission set (aws_ssoadmin_managed_policy_attachment) or it
    returns on the next sync. This control counts attachments and cannot be
    exempted per principal, so a break-glass role that must keep the policy is
    an accepted risk to record, not a finding to suppress.
  FIX

  tag checkov_id:            'CKV_AWS_274'
  tag checkov_category:      'IAM'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_iam_group_policy_attachment aws_iam_policy_attachment aws_iam_role aws_iam_role_policy_attachment aws_iam_user_policy_attachment aws_ssoadmin_managed_policy_attachment]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/iam_policy_attachment'
  tag nist:                  ['AC-3', 'AC-6']
  tag nist_r4:               ['AC-3', 'AC-6']
  tag cci:                   ['CCI-000213', 'CCI-002233']
  tag ksi:                   ['KSI-IAM-CTL']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  subject_resource = aws_iam_policy(policy_arn: "arn:#{input('aws_partition')}:iam::aws:policy/AdministratorAccess")

  # Always applicable. An account with no policy at all is the NON-COMPLIANT
  # state for this rule, not an inapplicable one — rendering it Not Applicable
  # would report the worst case as "does not apply here".
  impact 0.7

  describe 'aws_iam_policy_attachment' do
    it 'is configured for this account' do
      expect(subject_resource.exists?).to eq(true),
        'no account-level policy is set, so nothing constrains this'
    end
  end

  if subject_resource.exists?
    describe subject_resource do
      its('attachment_count') { should eq 0 }
    end
  end
end
